first=min(dates); print('earliest',first, first.strftime('%A'))
print('weekdays',collections.Counter(x.strftime('%A') for x in dates))
print('months',collections.Counter(x.strftime('%Y-%m') for x in dates))
empids={x['PESEL'] for x in emps}; taskids={x['task_id'] for x in tasks}
