  e=next(e for e in emps if e['PESEL']==x['employee_id'])
  if d<datetime.date.fromisoformat(e['hire_date']): vals.append('prehire')
 if h is not None and (h<=0 or h>24): vals.append('hours range')
 if vals: print(x['id'],vals,x)
